begin;

with input_items as (
  select *
  from jsonb_to_recordset('[]'::jsonb) as x(
    id uuid,
    parent_slug text,
    slug text,
    name text,
    item_type text,
    description text,
    sort_order integer,
    metadata jsonb,
    is_active boolean
  )
),
resolved_items as (
  select
    i.id,
    p.id as parent_id,
    i.slug,
    i.name,
    i.item_type::internal_knowledge_item_type as item_type,
    nullif(i.description, '') as description,
    i.sort_order,
    i.metadata,
    coalesce(i.is_active, true) as is_active
  from input_items i
  left join public.internal_knowledge_feature_items p on lower(p.slug) = lower(i.parent_slug)
)
insert into public.internal_knowledge_feature_items (
  id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, updated_at
)
select id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, now()
from resolved_items
on conflict (id) do update set
  parent_id = excluded.parent_id,
  slug = excluded.slug,
  name = excluded.name,
  item_type = excluded.item_type,
  description = excluded.description,
  sort_order = excluded.sort_order,
  metadata = public.internal_knowledge_feature_items.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

with input_blocks as (
  select *
  from jsonb_to_recordset('[{"id": "93d9e036-7c7e-5e33-a5b1-4b96bdf31e9b", "feature_slug": "admin-panel", "title": "Functions", "content": "### `bff_get_admin_profile()` → jsonb\n\nReturns the logged-in admin''s profile. Called on login and cached by the FE.\n\nPermission resources are sourced from `fn_admin_role_resource_catalog()`, including the `frontline` category and its tab-level resources.\n\n**Response shape:**\n```json\n{\n  \"success\": true,\n  \"merchant\": { \"merchant_id\", \"merchant_code\", \"merchant_name\" },\n  \"admin\": {\n    \"id\", \"auth_user_id\", \"email\", \"name\", \"phone\",\n    \"role_id\", \"role_code\", \"role_name\", \"is_system_role\",\n    \"active_status\",\n    \"role_config\": { \"default_path\", \"hide_sidebar\", \"hidden_menu_categories\", \"hidden_menu_items\", \"floating_menu\" }\n  },\n  \"permissions\": {\n    \"<category>\": {\n      \"<resource_code>\": { \"view\": bool, \"edit\": bool, \"display_name\": text }\n    }\n  }\n}\n```\n\n---\n\n### `bff_get_admin_menu()` → jsonb\n\nReturns sidebar structure filtered by:\n1. `admin_role_permissions` — only resources with `read` action are shown\n2. `admin_roles.config.hidden_menu_categories` — whole categories excluded\n3. `admin_roles.config.hidden_menu_items` — specific items excluded by id\n\nAlso returns `role_config` so FE can use it without a separate profile call.\n\n---\n\n### `fn_admin_role_resource_catalog()` → table\n\nCentral catalog for role-builder resources and profile permission output.\n\nColumns: `resource_code`, `display_name`, `category`.\n\nIncludes:\n- Existing loyalty, operations, settings, functional, admin, analytics, and event resources\n- `frontline` category resources: `front_line`, `frontline_upload_receipt`, `frontline_redemption_reward`, `frontline_burn_points_discount`, `frontline_adjust_points`, `frontline_claim_mission`, `frontline_asset_group`\n\n---\n\n### Default `frontline` system role\n\nGlobal system role:\n- `role_code`: `frontline`\n- `role_name`: `Frontline`\n- `merchant_id`: `NULL`\n- `is_system_role`: `true`\n- `config.default_path`: `/front-line`\n- `config.hide_sidebar`: `true`\n\nPermissions:\n- `front_line`: `read`\n- Front Line tab resources: `read`, `create`, `update`\n\nThis role is intended for staff who should only enter the Front Line page. FE route guards must enforce tab visibility using the tab-level permissions.\n\n---\n\n### `bff_upsert_admin_role(p_data jsonb)` → jsonb\n\nCreate or update a role. `p_data.id = null` → insert. `p_data.id = <uuid>` → update.\n\n**Input shape:**\n```json\n{\n  \"id\": null,\n  \"role_code\": \"frontline_sales\",\n  \"role_name\": \"Frontline Sales\",\n  \"active_status\": true,\n  \"permissions\": [\n    { \"resource\": \"event\", \"actions\": [\"read\", \"create\", \"update\"] }\n  ],\n  \"config\": {\n    \"default_path\": \"/choose-events\",\n    \"hide_sidebar\": true,\n    \"hidden_menu_categories\": [\"loyalty\", \"campaigns\", \"earning_config\", \"operations\", \"functional\"],\n    \"hidden_menu_items\": [],\n    \"floating_menu\": [...]\n  }\n}\n```\n\nIf `permissions` key is present, all existing permissions for the role are deleted and re-inserted (clean replace). If absent, permissions are untouched.\n\n---\n\n### `bff_get_admin_role(p_role_id uuid DEFAULT NULL)` → jsonb\n\n- `NULL` → returns all roles for merchant with permissions + config (for role list page)\n- `<uuid>` → returns single role detail for role editor form\n\n---", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Admin_Panel.md#L179 Functions", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "admin-panel", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "4b9b31454fa5635cc9328b0d1e88bd2b372d1d9fa421da2f502846cc5c855627", "truncated": false}, "is_active": true}, {"id": "f3cc594a-a8ea-5ba2-9a9d-ec57d8c720af", "feature_slug": "admin-panel", "title": "Tables", "content": "### `admin_roles`\n\nOne row per role per merchant. System roles (`is_system_role = true`) are created by superadmin and cannot be deleted by merchants.\n\n| Column | Type | Notes |\n|---|---|---|\n| `id` | uuid PK | `gen_random_uuid()` |\n| `merchant_id` | uuid | FK to `merchant_master` |\n| `role_code` | text NOT NULL | Machine-readable slug, e.g. `frontline_sales` |\n| `role_name` | text NOT NULL | Display name, e.g. `Frontline Sales` |\n| `is_system_role` | boolean | Default false. System roles cannot be deleted by merchant. |\n| `active_status` | boolean | Default true |\n| `config` | jsonb | UI config object (see below) |\n| `created_at` | timestamptz | |\n\n#### `config` JSONB shape\n\n```json\n{\n  \"default_path\": \"/choose-events\",\n  \"hide_sidebar\": true,\n  \"hidden_menu_categories\": [\"loyalty\", \"campaigns\", \"earning_config\", \"operations\", \"functional\"],\n  \"hidden_menu_items\": [\"amp\", \"forms-surveys\"],\n  \"floating_menu\": [\n    {\n      \"label\": \"Choose Events\",\n      \"icon\": \"mdi:calendar-check\",\n      \"url\": null,\n      \"page_path\": \"/choose-events\"\n    },\n    {\n      \"label\": \"Register Grower\",\n      \"icon\": \"mdi:account-plus\",\n      \"url\": null,\n      \"page_path\": \"/grower-registration\"\n    }\n  ]\n}\n```\n\n| Field | Type | Behaviour |\n|---|---|---|\n| `default_path` | text \\| null | After login, FE redirects here instead of home. Null = normal home. |\n| `hide_sidebar` | boolean | `true` = sidebar not rendered; content expands to full width. |\n| `hidden_menu_categories` | text[] | Categories to exclude from sidebar. Values: `loyalty`, `campaigns`, `earning_config`, `operations`, `functional`. `settings` is never filterable by category. |\n| `hidden_menu_items` | text[] | Specific `admin_menu_config.id` values to exclude regardless of category. |\n| `floating_menu` | array | Rendered as a fixed bottom bar. Each item: `label` (text), `icon` (Iconify name), `url` (external, optional), `page_path` (internal route, optional). Click prefers `page_path` over `url`. |\n\n#### Menu category values\n\n| `category` | Covers |\n|---|---|\n| `loyalty` | Rewards, Tiers, Currency, Forms, Integrations, AMP |\n| `campaigns` | Missions |\n| `earning_config` | Earn Methods (channels, marketplace) |\n| `operations` | Receipt upload, activity approval, code activation |\n| `functional` | Assets, Stores, Analytics |\n| `settings` | Team, Roles, Display, Global settings, Translation — never hidden by category |\n\n---\n\n### `admin_role_permissions`\n\nOne row per resource per role. Multiple resources per role.\n\n| Column | Type | Notes |\n|---|---|---|\n| `id` | uuid PK | |\n| `role_id` | uuid NOT NULL | FK to `admin_roles` |\n| `resource` | text NOT NULL | Resource code, e.g. `mission`, `reward`, `event` |\n| `actions` | text[] | Values: `read`, `create`, `update`, `delete`, `approve` |\n| `created_at` | timestamptz | |\n\n`read` in `actions` controls sidebar visibility via `bff_get_admin_menu()`. A menu item is shown only if `read` exists for its resource.\n\n#### Known resource codes\n\n| Resource | Category | What it gates |\n|---|---|---|\n| `currency` | loyalty | Currency config |\n| `reward` | loyalty | Reward list and builder |\n| `promo_code` | loyalty | Promo code lots |\n| `tier` | loyalty | Tier management |\n| `persona` | loyalty | Persona management |\n| `earn_channel` | earning_config | Earn channels |\n| `earn_marketplace` | earning_config | Marketplace orders |\n| `mission` | campaigns | Mission builder |\n| `purchase_approval` | operations | Receipt upload approval |\n| `activity_approval` | operations | Activity upload approval |\n| `earn_code_activate` | operations | Code activation |\n| `front_line` | frontline | Front Line page access |\n| `frontline_upload_receipt` | frontline | Front Line: Upload Receipt tab |\n| `frontline_redemption_reward` | frontline | Front Line: Redemption Reward tab |\n| `frontline_burn_points_discount` | frontline | Front Line: Burn Points for Discount tab |\n| `frontline_adjust_points` | frontline | Front Line: Adjust Points tab |\n| `frontline_claim_mission` | frontline | Front Line: Claim Mission tab |\n| `frontline_asset_group` | frontline | Front Line: Asset Group tab |\n| `display` | settings | Display settings |\n| `global_setting` | settings | Global settings |\n| `store` | functional | Store master |\n| `store_attribute` | functional | Store attributes |\n| `asset` | functional | Assets |\n| `analytics` | functional | Reports & Customer 360 |\n| `role` | settings | Role management |\n| `team` | settings | Team management |\n| `invite` | settings | Invitations |\n| `event` | — | Event features (Syngenta) |\n| `grower_registration` | — | Grower registration (Syngenta) |\n| `rice_survey` | — | Rice survey (Syngenta) |\n\n---\n\n### `admin_users`\n\nOne row per admin team member per merchant.\n\n| Column | Type | Notes |\n|---|---|---|\n| `id` | uuid PK | |\n| `auth_user_id` | uuid | FK to `auth.users` (Supabase Auth) |\n| `merchant_id` | uuid | |\n| `email` | text | |\n| `name` | text | |\n| `phone` | text | |\n| `role_id` | uuid NOT NULL | FK to `admin_roles` |\n| `active_status` | boolean | |\n| `invited_by` | uuid | Admin user who sent invitation |\n| `invited_at` | timestamptz | |\n| `accepted_at` | timestamptz | |\n| `shopify_user_id` | text | For Shopify-integrated merchants |\n| `cs_online_status` | text | CS agent online/offline/busy |\n| `cs_max_concurrent` | integer | Max simultaneous CS conversations |\n| `cs_skills` | jsonb | CS routing skills |\n| `created_at`, `updated_at` | timestamptz | |\n\n---\n\n### `admin_menu_config`\n\nStatic (superadmin-managed) table of all possible sidebar entries. Merchants do not add rows here; they control visibility through `admin_role_permissions` and `admin_roles.config`.\n\n| Column | Type | Notes |\n|---|---|---|\n| `id` | text PK | Slug, e.g. `rewards`, `amp`, `campaigns` |\n| `label` | text | Display label |\n| `href` | text | Route path (null for parent-only grouping nodes) |\n| `image` | text | Icon URL (inactive) |\n| `active_image` | text | Icon URL (active state) |\n| `badge` | text | Optional badge text |\n| `category` | text | One of the category values above |\n| `resource` | text | Matched against `admin_role_permissions.resource` |\n| `parent_id` | text | Self-reference; null = top-level parent |\n| `display_order` | integer | Sort order within parent |\n| `active_status` | boolean | Soft-disable without deleting |\n| `created_at` | timestamptz | |\n\n---", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Admin_Panel.md#L19 Tables", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "admin-panel", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "d786753d4b083bf6d75fe1fcd002062838d69916e27bff2e5bc38319c5c97560", "truncated": false}, "is_active": true}, {"id": "c6708d5e-ec9e-5064-9ec1-a86b50440035", "feature_slug": "admin-panel", "title": "Admin Panel Domain Reference", "content": "**Keywords:** admin_roles, admin_users, admin_role_permissions, admin_menu_config, role, permission, sidebar, menu, floating_menu, default_path, hide_sidebar, role_config, frontline, role_code, admin_invitations, admin_teams, admin_analytics_menu, platform_superadmin, is_platform_admin, superadmin, metabase_dashboard_id\n**Source:** `Admin_Panel.md`\n**Tables:**\n|---|---|\n| `admin_roles` | Role definitions per merchant. Contains `config JSONB` for UI settings (default_path, hide_sidebar, hidden_menu_categories, hidden_menu_items, floating_menu). System roles have `merchant_id = NULL` and `is_system_role = true` (CHECK `system_roles_must_be_global`). |\n| `admin_role_permissions` | Per-role resource + actions array (read, create, update, delete, approve) |\n| `admin_users` | Admin team members — linked to auth.users, holds role_id, CS profile fields |\n| `admin_menu_config` | Sidebar menu item definitions — id, label, href, category, resource, parent_id, display_order |\n| `admin_invitations` | Pending admin invitations |\n| `admin_teams` | CS agent team groupings |\n| `admin_analytics_menu` | Global (no merchant_id) list of Metabase dashboard menu items rendered on loyalty-admin `/analytics`. Columns: `label`, `section` (default `''Available dashboards''`), `metabase_dashboard_id text NULL` (NULL/empty → disabled placeholder item), `display_order int`, `active_status`, `created_at`, `updated_at` (trigger). Index on `(active_status, display_order)`. No RLS — access only via SECURITY DEFINER RPCs. |\n| Function | Type | Parameters | Returns |\n|---|---|---|---|\n| `bff_get_admin_profile` | BFF | none | Admin user info, merchant info, permissions map, `role_config` (default_path, hide_sidebar, floating_menu) |\n| `bff_get_admin_menu` | BFF | none | Sidebar items filtered by role permissions + role_config hidden categories/items; also returns `role_config` |\n| `bff_get_admin_role` | BFF | `p_role_id uuid DEFAULT NULL` | NULL → all roles list; with id → single role + permissions + config |\n| `bff_upsert_admin_role` | BFF | `p_data jsonb` | Create or update role with permissions + config in one call |\n| `bff_update_admin_menu_order` | BFF | `p_data jsonb` | Reorder menu items |\n| `get_admin_available_roles` | Backend | `p_merchant_id uuid` | Lightweight role list for dropdowns |\n| `get_admin_permissions` | Backend | `p_admin_user_id uuid` | Permission list for a user |\n| `is_platform_admin` | Helper | none | Returns `true` when `auth.uid()` maps to an active `admin_users` row whose role is `platform_superadmin`. Returns `false` for unauthenticated or non-superadmin callers (`COALESCE(..., false)`). SECURITY DEFINER, STABLE. Single source of truth for `superadmin_*` RPC auth checks. |\n| `assert_platform_admin` | Helper | none | Raises `42501` (`insufficient_privilege`) if `is_platform_admin()` is false. One-line gate at the top of every `superadmin_*` analytics RPC. Each RPC catches `insufficient_privilege` and returns `fn_response_error(''Forbidden'', ..., ''FORBIDDEN'')`. |\n| `bff_get_analytics_menu` | BFF | none | Any authenticated admin. Returns `{ items: [{id, label, section, metabase_dashboard_id, display_order}] }` — active rows only, ordered by `display_order`. Replaces the FE `DASHBOARD_MENU` hardcoded list on `/analytics`. |\n| `superadmin_list_analytics_menu` | Superadmin | none | Returns all rows (active + inactive) with `created_at` / `updated_at`, ordered by `display_order`. For the superadmin CRUD console. |\n| `superadmin_upsert_analytics_menu` | Superadmin | `p_id uuid DEFAULT NULL, p_label text, p_section text DEFAULT ''Available dashboards'', p_metabase_dashboard_id text DEFAULT NULL, p_display_order int DEFAULT NULL, p_active_status bool DEFAULT true` | `p_id` NULL → insert (auto-assigns next `display_order` if not provided). `p_id` set → update. Empty/whitespace `p_metabase_dashboard_id` is normalized to NULL (placeholder). Returns the full saved row under `data.item`. |\n| `superadmin_delete_analytics_menu` | Superadmin | `p_id uuid` | Hard delete. Returns `NOT_FOUND` if id doesn''t exist. |\n| `superadmin_reorder_analytics_menu` | Superadmin | `p_items jsonb` — array of `{id, display_order}` | Bulk-updates `display_order`. Returns `{updated, missing}` counts. Non-existent ids are skipped (counted in `missing`), not errored. |\n**Key Business Rules:**\n- `admin_roles.config` JSONB controls per-role UI: `default_path` (redirect on login), `hide_sidebar` (bool), `hidden_menu_categories` (text[]), `hidden_menu_items` (text[]), `floating_menu` (array of {label, icon, url, page_path})\n- `bff_get_admin_menu()` applies `hidden_menu_categories` and `hidden_menu_items` server-side — FE renders what comes back, nothing extra needed\n- `bff_get_admin_profile()` returns `role_config` — FE reads this once on login for redirect and floating menu\n- Settings category (`admin_menu_config.category = ''settings''`) is never filtered by `hidden_menu_categories` — only `hidden_menu_items` applies there\n- Floating menu icons use Iconify format (`mdi:calendar-check`, `mdi:account-plus`, etc.)\n- Permissions are stored as `resource` + `actions text[]` pairs; `read` controls sidebar visibility; `create/update/delete/approve` control edit access\n- `admin_analytics_menu` is global (not per-merchant). All 21 seed rows share `section = ''Available dashboards''`; rows 1–6 carry Metabase IDs (`176` Users, `177` Purchases, `136` Redemptions, `134` Wallet transactions, `178` Assets, `199` Packages); rows 7–21 have `metabase_dashboard_id = NULL` (rendered as disabled placeholders in the FE until a dashboard is wired).", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/admin-panel.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "admin-panel", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "b24f2f52600cdd123bcc8a72cc3e9683bfa7858fb7ea8562c864089d45e4d2a2", "truncated": false}, "is_active": true}, {"id": "7c275d5b-7e2c-5179-888a-9c29a947dd16", "feature_slug": "amp-ai-decisioning", "title": "4. Admin Journey", "content": "**Repo:** `Rocket-CRM/loyalty-admin`\n\n**Route map:**\n\n| Page Name | Current Route | BFF / Data Source |\n|---|---|---|\n| Agent Builder (list) | `/agent-builder` | `bff_list_agents` |\n| Agent Builder (editor) | `/agent-builder` (SPA view switch) | `bff_get_agent_full`, `bff_upsert_agent_with_children` |\n| AMP Analytics | `/amp-analytics` | `bff_amp_analytics_overview`, `bff_amp_analytics_agent`, `bff_amp_analytics_user_timeline` |\n| Workflow List | `/workflow-list` | (Workflow builder references agent by ID) |\n\n### 4a. Create a New Agent\n\n1. From **Agent Builder** list, click **\"Create Agent\"**\n2. Editor opens with 4 tabs: **Configuration**, **Actions**, **Outcomes**, **Scheduling & Guardrails**\n3. **Configuration tab**: fill name (required), description, select objective and tone, add context hint, set max actions per execution. Optionally expand Deliberation Settings to adjust cycle count and wait durations\n4. **Actions tab**: click **\"+ Add Action\"** to add action rows. For each: select action type, set variable ranges (e.g., points min/max), configure action constraints, add eligibility conditions\n5. **Outcomes tab**: click **\"+ Add Outcome\"** to add outcome rows. Select event type from dropdown (pre-populates classification, attribution window, counting method from seed table). Set one outcome as primary with a target conversion rate\n6. **Scheduling & Guardrails tab**: set cooldown hours, enable quiet hours with time window, add blackout dates. Add agent-level constraints using the natural-language builder (\"No more than X metric per scope per window\")\n7. Click **\"Save\"** — calls `bff_upsert_agent_with_children` to save agent + actions + outcomes atomically\n8. Return to agent list\n\n### 4b. Edit an Existing Agent\n\n1. From **Agent Builder** list, click any agent row\n2. Editor opens pre-populated — all 4 tabs editable\n3. Modify, then **\"Save\"**. **\"Discard\"** reverts to last saved state\n\n### 4c. Manage Agent List\n\n1. **Agent Builder** list shows: Name, Objective, Tone, Active badge, Action count, Outcome count, Created date\n2. Toggle active/inactive directly from list\n\n### 4d. Use Agent in a Workflow\n\n1. From **Workflow List**, open or create a workflow\n2. Add an agent node to the workflow graph\n3. In the agent node sidebar, select an existing agent by name (stores `agent_config_id` reference)\n4. Workflow routes on agent output: action taken → true handle, no action → false handle\n\n### 4e. View Agent Performance\n\n1. From **AMP Analytics**, click an agent row in the Agent Performance table\n2. **Agent Detail** view shows: Users Actioned, Conversion Rate vs Target, Total Value, Average Hours to Conversion, Negative Outcome Rate\n3. Charts: Conversion Gauge, Outcome Breakdown, Action Effectiveness, Deliberation Decision Distribution, Daily Activity, Cost Breakdown\n4. Constraint usage cards with progress bars\n5. Recent Decisions table — click any row to see **User Timeline**\n\n### 4f. Common Admin Mistakes\n\n- Creating an agent with no actions configured — AI has nothing to do, always skips\n- Setting constraints too tight (e.g., 1 action per user per month) — agent rarely acts\n- Not setting a primary outcome — performance tracking has no main KPI to optimize against\n- Setting max deliberation cycles to 1 — eliminates the observe-wait pattern, agent becomes single-shot\n- Forgetting to mark agent as active — workflow agent node silently skips", "content_format": "markdown", "knowledge_type": "admin_journey", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/amp-ai-decisioning.md#L110 4. Admin Journey", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "amp-ai-decisioning", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "cb0050c3d5037b12edcd3000cb6f393848a02dec27759740f1b14ab1a2262a24", "truncated": false}, "is_active": true}, {"id": "10a103bc-c87e-5401-b376-f6588a523b23", "feature_slug": "amp-ai-decisioning", "title": "7. Business Rules", "content": "**Rule:** The AI''s default posture is observational — most triggers result in WAIT, not ACT.\n**Example:** 100 users enter a win-back workflow → ~15 get immediate action, ~65 enter deliberation (wait-and-reassess), ~20 are skipped.\n\n**Rule:** Constraints are enforced at two layers — AI self-regulation and MCP hard stop. Both use the same usage data.\n**Example:** AI reads \"3 actions remaining this week\" → picks one action. If the AI somehow requests 4, the MCP tool rejects the 4th.\n\n**Rule:** The AI only sees actions explicitly configured for the agent. Ineligible actions (by user eligibility) are structurally removed before the AI reasons.\n**Example:** Agent has \"award_points\" with eligibility \"balance < 1000\". User has 1500 balance → the AI never sees the points action in its tool list.\n\n**Rule:** Agent performance aggregates across all workflows referencing that agent.\n**Example:** \"Win-Back VIPs\" agent used in 3 campaigns → performance summary reflects all 3 campaigns'' outcomes combined.\n\n**Rule:** Outcome attribution uses a per-outcome window. Different outcomes can have different windows.\n**Example:** Purchase attribution = 168 hours (7 days). Email click attribution = 2 hours. Both tracked for the same agent.\n\n**Rule:** One primary outcome per agent, enforced by partial unique index.\n**Example:** Attempt to set two outcomes as primary → database rejects the second.\n\n**Rule:** Deliberation history is passed to the AI in each cycle. The AI compares \"what I was watching for\" against fresh user data.\n**Example:** Cycle 0: AI says \"wait 3 days, watching for a purchase.\" Cycle 1: AI sees no purchase occurred → decides to act with 200 points.\n\n**Rule:** Cost normalization converts action units to THB. Points = 0.10 THB/point, LINE = 0.30 THB/message, SMS = 0.80 THB/message.\n**Example:** Awarding 200 points costs 20 THB normalized. A \"cost < 1000 per agent per month\" constraint tracks against this normalized value.\n\n**Rule:** Agent scheduling controls override workflow-level scheduling for agent nodes.\n**Example:** Workflow has cooldown 12h, agent has cooldown 24h → agent''s 24h cooldown applies.\n\n**Rule:** Constraint usage is pre-computed every 10 minutes via pg_cron, cached in Redis (10-min TTL). Usage data can be up to ~20 minutes stale — conservative (never over-counts).\n**Example:** Agent awarded points 5 minutes ago → constraint cache may not reflect it yet, but enforcement layer prevents double-spend.", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["customer_success", "product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/amp-ai-decisioning.md#L267 7. Business Rules", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "amp-ai-decisioning", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "da7ae4a69f0f0154385497113144e55fb3cbb85797db906fb99d580828b9abe1", "truncated": false}, "is_active": true}, {"id": "006368e6-bc08-5abb-8b78-65d020c5efd0", "feature_slug": "amp-ai-decisioning", "title": "3. Configuration Reference", "content": "### Configuration Tab — Basic Info\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| Name | Agent display name | \"Win-Back VIPs\" | Required |\n| Description | Internal description | \"Re-engage customers inactive 90+ days\" | Empty |\n| Objective | AI reasoning approach | `re_engage` | None (select required) |\n| Tone | Message style | `friendly` | None (select required) |\n| Context Hint | Free-text AI guidance | \"Lapsed VIP customers\" | Empty |\n| Max Actions Per Execution | Actions per user per cycle | 3 | 3 |\n\n### Configuration Tab — Deliberation Settings (collapsible)\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| Max Cycles | Observe-wait-decide iterations | 5 | 3 |\n| Default Wait | Sleep duration if AI doesn''t specify | `2d` | `2d` |\n| Max Wait | Cap on any single wait | `7d` | `7d` |\n| Total Timeout | Maximum time from first to last cycle | `14d` | `14d` |\n\n### Actions Tab\n\nEach agent action row:\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| Action Type | Which MCP tool to use | `award_points` | Required (select) |\n| Name | Display label | \"Welcome bonus points\" | Auto from type |\n| Variable Config | Ranges the AI picks from | `amount: {min: 50, max: 500}` | Per action type |\n| Action Constraints | Per-action execution limits | `max_amount_per_execution: 500` | None |\n| Eligibility Conditions | User must meet these to receive this action | `points_balance < 1000` | None (all eligible) |\n| Enabled | Toggle without deleting | true | true |\n\nAvailable action types: `award_points`, `award_tickets`, `assign_tag`, `remove_tag`, `assign_persona`, `assign_earn_factor`, `submit_form`, `send_line_message`, `send_sms`, `add_to_audience`, `remove_from_audience`.\n\n### Outcomes Tab\n\nEach outcome row:\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| Event Type | What event to track | `purchase_completed` | Required (dropdown from seed table) |\n| Classification | Success/failure ranking | `best` | From seed table default |\n| Weight Column | Numeric column for value weighting | `final_amount` | None |\n| Attribution Window | Hours after action to attribute | 168 (7 days) | From seed table |\n| Counting Method | `cumulative` (every event) or `binary` (once) | `cumulative` | From seed table |\n| Is Primary | Main KPI — one per agent | true | false |\n| Target Conversion Rate | Goal rate for primary outcome | 0.20 (20%) | None |\n| Event Filter | Optional condition on event properties | `amount > 500` | None |\n\n### Scheduling & Guardrails Tab\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| Cooldown Hours | Min gap between actions per user | 24 | None (no cooldown) |\n| Quiet Hours Enabled | Suppress actions during off-hours | true | false |\n| Quiet Hours Start/End | Time window | 22:00–08:00 | 22:00–08:00 |\n| Quiet Hours Timezone | Which timezone | Asia/Bangkok | Asia/Bangkok |\n| Blackout Dates | Specific no-action dates | 2025-12-25 | Empty |\n\nAgent-level constraint rows (natural-language builder):\n\n| Component | Options | Example |\n|---|---|---|\n| Metric | actions, points, tickets, messages, cost | `points` |\n| Limit | Numeric | `500` |\n| Scope | per user, total | `per user` |\n| Window | per execution, per day, per week, per month | `per month` |\n\nReads as: \"No more than 500 points per user per month.\"", "content_format": "markdown", "knowledge_type": "configuration_reference", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/amp-ai-decisioning.md#L37 3. Configuration Reference", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "amp-ai-decisioning", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "be20e8a7144682168ea69f1b289fce0b9508bc5f4330a406dd5ae3cf3f787fe4", "truncated": false}, "is_active": true}, {"id": "54f488c8-0662-5653-b54d-4cdf021f5c3c", "feature_slug": "amp-ai-decisioning", "title": "2. Key Concepts", "content": "**Agent** — A reusable AI configuration that defines how the AI reasons about a specific marketing goal. Contains an objective, tone, allowed actions, constraints, and deliberation settings. Created in the Agent Builder and referenced by workflow agent nodes. Example: \"Win-Back VIPs\" agent with objective `re_engage`, 3 allowed actions, max 500 points/month budget.\n\n**Agent Action** — A specific action the AI is permitted to use, configured per-agent. Each action has a type (e.g., `award_points`), variable ranges the AI can choose within (e.g., 50–500 points), per-action constraints, and eligibility conditions. The AI only sees the actions explicitly configured — not the merchant''s full catalog.\n\n**Objective** — The strategic approach the AI takes when reasoning. Values: `re_engage`, `drive_purchase`, `redeem_points`, `tier_upgrade`, `win_back`, `upsell`. Shapes the AI''s reasoning style — two agents with the same outcome but different objectives reason differently.\n\n**Tone** — Communication style for AI-generated messages. Values: `urgent`, `friendly`, `exclusive`, `celebratory`.\n\n**Context Hint** — Free-text guidance from the marketer to the AI. Example: \"These are lapsed VIP customers who haven''t purchased in 90 days.\" Included in the AI prompt alongside user data.\n\n**Deliberation** — The observe-wait-act loop. On each cycle, the AI fetches fresh user data and decides: ACT (execute actions), WAIT (sleep and reassess later), or SKIP (user doesn''t fit). Multiple cycles are spaced days apart, controlled by deliberation settings.\n\n**Constraint** — A limit on agent behavior. Format: \"No more than [limit] [metric] per [scope] per [time_window].\" Metrics: `actions`, `points`, `tickets`, `messages`, `cost`. Scopes: `per_user`, `per_agent`. Windows: `per_day`, `per_week`, `per_month`. Enforced at two layers — the AI reads constraints and self-regulates, then MCP action tools enforce as a hard stop.\n\n**Action Constraint** — Per-action limits on a single execution. Example: max 500 points per execution, 1,000 points budget per month. Distinct from agent-level constraints.\n\n**Outcome** — A measurable event that defines success or failure for the agent. Each outcome has an event type (e.g., `purchase_completed`), a classification (`best` through `worst`), an attribution window, and optionally a weight column. One outcome per agent is marked primary — the main KPI.\n\n**Attribution** — The process of linking an outcome event back to the agent action that likely caused it. If a user was actioned by the agent and then completed a purchase within the attribution window (e.g., 7 days), that purchase is attributed to the agent.\n\n**Cost Normalization** — Converts action units to a normalized monetary value (THB). Points = 0.10 THB each, LINE message = 0.30 THB, SMS = 0.80 THB. Used for budget constraints and performance tracking.\n\n**Scheduling Controls** — Time-based restrictions: cooldown hours (minimum gap between actions per user), quiet hours (suppress actions during off-hours), blackout dates (no actions on specific dates).", "content_format": "markdown", "knowledge_type": "key_concepts", "perspectives": ["customer_success", "general", "product", "testing"], "output_uses": ["agent_context", "product_docs", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/amp-ai-decisioning.md#L11 2. Key Concepts", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "amp-ai-decisioning", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "585585136ab57f41c5fe7a3ad8009bd8509c4e16647b24e93bf89efc29471b32", "truncated": false}, "is_active": true}, {"id": "1b4670c4-9105-5360-b5db-621c4d2c1167", "feature_slug": "amp-ai-decisioning", "title": "6a. For Customer Success / Support", "content": "**Elevator pitch:** \"AI Decisioning lets the system decide what to send each customer and when, instead of one-size-fits-all rules. The marketer sets the goal and guardrails — the AI picks the right action for each person.\"\n\n**Top 5 support questions:**\n\n| Question | Answer |\n|---|---|\n| \"Why did this member get 200 points instead of 100?\" | The AI chose the amount within the configured range based on user context. Check the agent''s action variable config for the allowed range, and the AMP Analytics User Timeline for the reasoning. |\n| \"A member says they got a message at 2 AM\" | Check quiet hours settings on the agent — either quiet hours is disabled or the timezone is wrong. |\n| \"Why hasn''t a member received anything from the campaign?\" | The AI may have decided to WAIT or SKIP. Check AMP Analytics → User Timeline for deliberation history. The AI skips ~10-20% of users who don''t fit. |\n| \"The agent isn''t doing anything for anyone\" | Check: is the agent active? Does it have actions configured? Are constraints too tight? Are eligibility conditions too narrow? |\n| \"A member received the same message twice\" | Check cooldown_hours setting — if null, no gap is enforced. Check per_user constraints. |", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["customer_success"], "output_uses": ["agent_context", "help_center", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/amp-ai-decisioning.md#L190 6. Perspectives / 6a. For Customer Success / Support", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "amp-ai-decisioning", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "e8bcf997b05530036de58d5ae2de76788a566ecdbdefb11e3348c3bfdb6edfdf", "truncated": false}, "is_active": true}, {"id": "f404f186-e12c-55cc-823d-254367a53112", "feature_slug": "amp-ai-decisioning", "title": "1. Overview", "content": "AMP AI Decisioning replaces static if/then marketing automation with an AI agent that makes per-user decisions in real time. Instead of a marketer building a rule that says \"if inactive 30 days, send 100 points,\" the marketer defines an objective (\"re-engage lapsed customers\"), configures which actions the AI may use (award points, send LINE messages, assign tags), and sets constraints (budget, frequency limits). The AI then decides — for each individual user — whether to act, what to do, and when.\n\nThe system''s default posture is observational. When a workflow trigger fires, the AI assesses the user''s context (purchase history, point balance, recent activity), checks constraint headroom, and usually decides to **wait**. Over multiple deliberation cycles — spaced days apart — the AI re-evaluates with fresh data until the timing is right. Expected distribution across all triggers: 15-20% act, 60-70% wait (then eventually act or skip), 10-20% skip immediately.\n\nAgents are reusable entities, independent of any single workflow. One agent can be referenced by multiple campaigns. Performance data (conversion rates, action effectiveness) aggregates across all workflows using that agent — so the AI learns from every campaign it participates in.", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing", "product"], "output_uses": ["agent_context", "product_docs", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/amp-ai-decisioning.md#L3 1. Overview", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "amp-ai-decisioning", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "c47bf8f5d1cfec6e685d8e782f6e8e0058ebea18ad3fa7d2676dab4ea9045e06", "truncated": false}, "is_active": true}, {"id": "28da4d73-1764-5c91-8bbc-42e92dc9ca01", "feature_slug": "amp-ai-decisioning", "title": "8. Related Features", "content": "| Feature | Connection to AMP AI Decisioning |\n|---|---|\n| AMP Workflows (Rule-Based) | AI Decisioning agents are placed as nodes within AMP workflows. Rule-based and AI nodes can coexist in the same workflow. See `AMP - Rule Based.md`. |\n| Currency | `award_points` and `award_tickets` actions deduct from / add to member wallets. See `Currency.md`. |\n| Rewards | AI can influence redemption behavior through point awards and persona changes that affect eligibility and pricing. See `Reward.md`. |\n| Tags & Personas | `assign_tag`, `remove_tag`, and `assign_persona` actions modify member profiles. See `Tag_and_Persona.md`. |\n| Activity/Earning | `assign_earn_factor` action modifies the member''s points earning multiplier. See `Activity_Based_Earning.md`. |\n| Forms | `submit_form` action can trigger form-related workflows. See `Forms.md`. |\n| Audiences | `add_to_audience` and `remove_from_audience` actions manage segment membership. |", "content_format": "markdown", "knowledge_type": "related_features", "perspectives": ["general", "product"], "output_uses": ["agent_context", "product_docs"], "scope": "general", "source_ref": "requirements/feature-docs/amp-ai-decisioning.md#L299 8. Related Features", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "amp-ai-decisioning", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "d74eef0f28e95d3e04be2593817473a5a55439ebb2332b4113484cafb8ca26dd", "truncated": false}, "is_active": true}, {"id": "5c1d0ff2-c9fc-5516-9d44-cfaa99219140", "feature_slug": "amp-ai-decisioning", "title": "6c. For Testers", "content": "**Config → expected behavior:**\n\n| Config | Expected behavior |\n|---|---|\n| Agent with 0 actions | AI always returns SKIP |\n| Agent with constraints: 0 actions per_user per_day | All action attempts rejected by enforcement layer |\n| Agent with max_deliberation_cycles = 1 | Single assessment, no wait cycles — act or skip immediately |\n| Cooldown 24h, user actioned 1h ago | AI reads cooldown from constraints, skips or waits |\n| Quiet hours 22:00–08:00 Bangkok, trigger at 23:00 Bangkok | Action suppressed until 08:00 |\n| Blackout date = today | All actions suppressed for the day |\n| Action with eligibility: points_balance < 1000, user has 1500 | That action excluded from AI''s available options |\n| Action variable_config: amount min=50 max=500, AI awards 600 | Rejected by action constraint enforcement |\n| Primary outcome target = 0.20, actual = 0.12 | Performance summary shows \"below target\" |\n| Agent used in 3 workflows | Performance aggregates across all 3 workflows |\n\n**Business rules as assertions:**\n\n- ASSERT: AI decision is one of `act`, `wait`, or `skip` — no other values\n- ASSERT: When AI decides `wait`, a `wait_duration` and `watching_for` are returned\n- ASSERT: When AI decides `act`, executed actions stay within variable_config ranges\n- ASSERT: Constraint enforcement rejects any action that would exceed a limit, even if the AI chose it\n- ASSERT: After max_deliberation_cycles reached without action, status = `exhausted`, routes false\n- ASSERT: Deliberation timeout exceeded → deliberation stops, routes false\n- ASSERT: Agent-level constraint and action-level constraint both apply — stricter one wins\n- ASSERT: Outcome attribution only counts events within attribution_window_hours of the action\n- ASSERT: Only one outcome per agent can have `is_primary = true`\n- ASSERT: Cost is tracked per action: points = 1/point, LINE = 1/message, SMS = 2/message, tags/personas = 0\n\n**Decision status model:**\n\n| Status | Event Type | When |\n|---|---|---|\n| `acted` | `agent_decided_act` | AI executed one or more actions |\n| `waiting` | `agent_decided_wait` | AI deferred, will reassess after sleep |\n| `skipped` | `agent_decided_skip` | AI determined user doesn''t fit |\n| `exhausted` | `agent_decided_skip` | Max cycles reached with no action |\n\nEach log entry includes: cycle number, decision, reasoning, watching_for (if wait), wait_duration (if wait), actions_taken (if act).\n\n**Deliberation timeline test:** Verify in `amp_workflow_log` — filter by `event_type LIKE ''agent_decided_%''` for a specific user + workflow, ordered by `created_at`. Should show sequential cycles with increasing cycle numbers.", "content_format": "markdown", "knowledge_type": "testing_guidance", "perspectives": ["testing"], "output_uses": ["agent_context", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/amp-ai-decisioning.md#L190 6. Perspectives / 6c. For Testers", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "amp-ai-decisioning", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "4580fd572dd215d41791df751e202d9b6fcbb56cc61b921ee9c25ec083f3f512", "truncated": false}, "is_active": true}, {"id": "3fa8d228-2aa8-5a70-b765-a8f16184a430", "feature_slug": "amp-ai-decisioning", "title": "5. Member Experience", "content": "**Repo:** `Rocket-CRM/loyalty-user`\n\n**Route map:**\n\n| Page / Component | Current Route | Data Source |\n|---|---|---|\n| N/A — no direct member UI | — | — |\n\nMembers do not interact with AI Decisioning directly. There is no \"AI agent\" screen in the member app. Instead, members experience the *results* of AI decisions:\n\n- **Points awarded** — appears in wallet balance and transaction history\n- **LINE messages received** — personalized message in LINE chat\n- **SMS received** — text message to phone\n- **Tag assigned** — affects eligibility for rewards, missions, or campaigns\n- **Persona changed** — alters catalog visibility and pricing\n- **Earn factor assigned** — modifies points earning rate\n- **Added to audience** — included in targeted campaign segments\n\nThe member sees the same UI as any other platform action — the only difference is that the AI chose the action, timing, and parameters rather than a static rule.", "content_format": "markdown", "knowledge_type": "user_experience", "perspectives": ["frontend", "marketing", "testing"], "output_uses": ["frontend_context", "marketing_content", "qa_testing"], "scope": "user_fe", "source_ref": "requirements/feature-docs/amp-ai-decisioning.md#L168 5. Member Experience", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "amp-ai-decisioning", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "43b3f2dc66ea7df6dcdff56e39809627c9603392e1b5abfc4402622563672cc6", "truncated": false}, "is_active": true}, {"id": "f239a077-62bd-507b-be3b-eaa945062cc3", "feature_slug": "amp-ai-decisioning", "title": "6b. For Marketing", "content": "**Value proposition:** AI Decisioning shifts marketing from \"blast everyone the same thing\" to \"let the AI figure out the right action for each person.\" A marketer defines the goal (re-engage, drive purchase, upsell), sets the budget and constraints, and the AI handles per-user personalization — choosing between awarding points, sending a message, adjusting earn factors, or doing nothing.\n\n**Use-case stories:**\n\n1. **Win-back campaign** — Agent objective: `win_back`. Allowed actions: award 50–500 points, send LINE message. AI sees a user hasn''t purchased in 90 days → cycle 1: waits 3 days watching for organic return → cycle 2: user still inactive, awards 200 points + sends a LINE message with friendly tone. Constraint: max 500 points per user per month.\n\n2. **Tier upgrade push** — Agent objective: `tier_upgrade`. Allowed actions: assign earn factor (2x multiplier), send LINE message. AI targets users close to the next tier threshold, nudging with a temporary earn boost at the right moment.\n\n3. **Cross-sell personalization** — Agent objective: `upsell`. Actions: tag assignment, LINE message. AI identifies purchase patterns and assigns interest-based tags, then sends targeted product recommendations. Primary outcome: purchase within 7 days.\n\n**Differentiators:**\n- **Per-user decisioning** — each member gets individually assessed, not batch-processed\n- **Observe-wait-act** — the AI watches and waits for the right moment rather than firing immediately\n- **Budget-aware** — constraints prevent overspending; cost normalization tracks real monetary impact\n- **Self-improving** — outcome attribution and performance tracking mean the AI learns which actions drive results", "content_format": "markdown", "knowledge_type": "value_proposition", "perspectives": ["marketing", "sales"], "output_uses": ["marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/amp-ai-decisioning.md#L190 6. Perspectives / 6b. For Marketing", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "amp-ai-decisioning", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "7bc7ea6f0eb9cc37ca3f934e1f81686f21525bcae43acfbcc6d6369974fd5791", "truncated": false}, "is_active": true}, {"id": "6e4dcb7a-36c8-5671-8ddf-90269e2a2e8d", "feature_slug": "amp-workflows", "title": "4. Admin Journey", "content": "**Repo:** `Rocket-CRM/loyalty-admin`\n\n**Route map:**\n\n| Page Name | Current Route | BFF / Data Source |\n|---|---|---|\n| Workflow List | `/workflow-list` | `amp_workflow` table (direct query, `scope=''user''`) |\n| Workflow Builder | `/workflow-list` (inline canvas view) | `bff_get_amp_workflow_full`, `bff_get_workflow_collections`, `bff_get_amp_action_options` |\n| Audience Builder | `/audience-builder` | `bff_list_audiences`, `bff_create_audience`, `bff_activate_audience` |\n| AMP Analytics | `/amp-analytics` | `bff_amp_analytics_overview`, `bff_amp_analytics_workflow` |\n\n### 4a. Create a New Workflow\n\n1. From **Workflow List**, click **\"Create workflow\"** button\n2. **Workflow Builder** opens with a single Entry Condition node on the canvas and the node palette sidebar\n3. Configure the entry condition: select collection (table), field, operator, value — this defines what triggers the workflow\n4. Drag nodes from the **Node Palette** (left sidebar) onto the canvas — grouped as Messages, Loyalty, Audience, Integration, Logic\n5. Connect nodes by dragging from output handles to input handles. Condition and Agent nodes have two outputs: true (green) and false (red)\n6. Click any node to open its **Config Panel** (right sidebar) and configure settings\n7. Set workflow name and description in the **Settings** panel\n8. Click **\"Save\"** — saves as inactive. Toggle **\"Active\"** switch to activate (starts processing events)\n\n### 4b. Edit an Existing Workflow\n\n1. From **Workflow List**, click any workflow row\n2. **Workflow Builder** opens with the existing graph loaded (nodes, edges, triggers)\n3. Modify nodes, edges, or settings. Save when done.\n\n### 4c. Manage the Workflow List\n\n1. **Workflow List** displays all `scope=''user''` workflows with columns: Name, Status (badge), Run Mode, Domain, Last Updated\n2. **Toggle status**: activate/deactivate directly from the list via toggle switch\n3. **Duplicate**: creates a copy with \"(Copy)\" suffix, set to inactive\n4. **Batch Run**: manually trigger evaluation for all qualifying users (when `run_mode=''batch''`)\n\n### 4d. View Analytics\n\n1. From **AMP Analytics**, the **Overview Dashboard** shows: total workflows, executions, users reached, actions performed\n2. Click a workflow row → **Workflow Detail** with per-workflow stats, daily volume charts, action funnel, recent executions\n3. Click a user row → **User Timeline** showing the full execution path with color-coded event dots\n4. Time range filter: 7D / 30D / 90D / All / Custom date range\n\n### 4e. Common Admin Mistakes\n\n- Saving a workflow with no entry condition configured → workflow has no trigger, never fires\n- Activating a workflow before finishing node configuration → incomplete actions fail at execution\n- Creating a condition that references a table not yet on the CDC pipeline → trigger never arrives\n- Setting wait duration too short for the use case (e.g., 5 minutes for a \"re-engagement\" flow)\n- Forgetting to activate after saving — workflows default to inactive", "content_format": "markdown", "knowledge_type": "admin_journey", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/amp-workflows.md#L82 4. Admin Journey", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "amp-workflows", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "f87d54c66aac57406bcf1f9b8d10ebbf8ee26ed55cd62f46c7a54d62c5e1a7b6", "truncated": false}, "is_active": true}, {"id": "75527521-cb09-5efa-b3de-1d2049942511", "feature_slug": "amp-workflows", "title": "7. Business Rules", "content": "**Rule:** Triggers are auto-derived from entry condition fields. When a workflow is saved, `bff_upsert_amp_workflow_with_graph` scans condition nodes for their `collection` (table name) and creates/updates `amp_workflow_trigger` records.\n**Example:** Entry condition queries `wallet_ledger.transaction_type = ''earn''` → trigger created for `wallet_ledger INSERT`.\n\n**Rule:** The entry node is the first node with no incoming edges. There is no explicit \"trigger\" node type.\n**Example:** A workflow with nodes A→B→C where A has no incoming edges → A is the entry node.\n\n**Rule:** Condition nodes branch via `source_handle`. True path follows the `true` handle edge; false path follows the `false` handle. If no edge exists for a branch, execution stops on that path.\n**Example:** Condition \"points > 500\" evaluates to false, no false-edge → execution completes without running further nodes.\n\n**Rule:** Wait nodes use Inngest''s `step.sleep()`. The workflow pauses for the exact duration, then resumes. Inngest persists state across server restarts.\n**Example:** Wait 7 days → execution pauses, Inngest scheduler resumes after 7 days.\n\n**Rule:** Workflows default to `is_active = false`. They must be explicitly activated to process events. Deactivating stops new executions but does not cancel in-flight ones.\n**Example:** Admin saves workflow → inactive. Toggles active → starts processing CDC events.\n\n**Rule:** All action side-effects are tracked with `source_type=''amp''` and `source_id=workflow_id`, enabling audit trail back to the originating workflow.\n**Example:** Points awarded by workflow → `wallet_ledger` row has `source_type=''amp''`.\n\n**Rule:** Inngest retries failed steps 3 times with exponential backoff (1s → 2s → 4s). 4xx errors do not retry. 5xx and network errors do.\n**Example:** LINE API returns 500 → retried 3 times. LINE API returns 400 (bad request) → fails immediately.\n\n**Rule:** CDC pipeline filters inserts only (`op = ''c''`) and applies table-specific business filters (wallet: `earn` transactions only; purchase: `completed` only). Deduplication via Redis with a 5-minute window.\n**Example:** Points deduction (not `earn`) → AmpConsumer filters it out, no workflow triggered.", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["customer_success", "product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/amp-workflows.md#L233 7. Business Rules", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "amp-workflows", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "838552343d706f9bb2ac7dd2741619de8bac168dac9bf9ed51cbdaf13df3e9b0", "truncated": false}, "is_active": true}, {"id": "2ce66c03-67d6-58eb-8e08-c6bbb1012236", "feature_slug": "amp-workflows", "title": "3. Configuration Reference", "content": "### Workflow Settings\n\n| Setting | What it controls | Options | Default |\n|---|---|---|---|\n| Name | Display name in workflow list | Free text | \"New Workflow\" |\n| Code | Unique identifier per merchant | Auto-generated `wf_{timestamp}` | Auto |\n| Description | Optional notes | Free text | Empty |\n| Status | Whether the workflow processes events | Active / Inactive | Inactive |\n| Run Mode | How the workflow is triggered | `event` (CDC-driven), `batch` (manual) | `event` |\n| Scope | Visibility classification | `user` (marketer-facing), `system` (infrastructure) | `user` |\n| Domain | What the workflow automates | `campaign`, `audience` | `campaign` |\n\n### Node Types and Configuration\n\n**Condition Node**\n\n| Setting | What it controls | Example |\n|---|---|---|\n| Match mode | How groups combine | `all` (AND) / `any` (OR) |\n| Collection (table) | Which data table to query | `wallet_ledger`, `purchase_ledger`, `user_accounts` |\n| Field | Column to evaluate | `amount`, `transaction_type`, `tier_id` |\n| Operator | Comparison type | `=`, `>`, `<`, `contains`, `SUM >`, `COUNT >=` |\n| Value | Target value | `100`, `earn`, specific UUID |\n\n**Action Node** — sub-types grouped by category:\n\n| Category | Action | Key settings |\n|---|---|---|\n| Messages | LINE Message | `content` (text), `json_content` (Flex message) |\n| Messages | SMS | `message` (text with variables) |\n| Loyalty | Award Currency | `currency` (points/ticket), `amount`, `ticket_type_id` |\n| Loyalty | Assign Tag | `tag_id` |\n| Loyalty | Remove Tag | `tag_id` |\n| Loyalty | Assign Persona | `persona_id` |\n| Loyalty | Earn Factor | `earn_factor_id`, `window_end_days` |\n| Loyalty | Submit Form | `form_id`, `field_values` |\n| Audience | Add to Audience | `audience_id` |\n| Audience | Remove from Audience | `audience_id` |\n| Integration | Webhook | `method`, `url`, `headers`, `body`, `timeout_seconds` |\n\n**Wait Node**\n\n| Setting | Options | Example |\n|---|---|---|\n| Duration | Numeric value | `3` |\n| Unit | minutes, hours, days, weeks, months | `days` |\n\n**Agent Node** — Select a pre-configured AI agent by ID. See AMP AI Decisioning guide.", "content_format": "markdown", "knowledge_type": "configuration_reference", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/amp-workflows.md#L31 3. Configuration Reference", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "amp-workflows", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "5943816e1f74e356c4936e9b529a4c4e2f7d705d07e93c65ad45d408bb86096d", "truncated": false}, "is_active": true}, {"id": "3c300f1e-4da3-53d1-ae6e-fea2be52d18c", "feature_slug": "amp-workflows", "title": "2. Key Concepts", "content": "**Workflow** — An automated sequence of steps stored as a directed graph (nodes + edges). Has a name, code, active/inactive status, and a run mode (`event` for CDC-triggered, `batch` for manual). Example: \"Welcome Series\" triggers on new user signup, sends greeting, waits 2 days, checks purchase history, branches.\n\n**Node** — A single step in the workflow. Six types exist: condition, action, wait, message (deprecated — now action sub-types), agent, and API call. Each node has a type, configuration, and canvas position.\n\n**Edge** — A directional connection between two nodes. Carries a `source_handle` that determines branching: `default` (linear flow), `true` (condition passed), or `false` (condition failed).\n\n**Entry Node** — The first condition node with no incoming edges. This is where execution begins. Triggers are auto-derived from which database tables the entry condition references.\n\n**Trigger** — A mapping from a CDC event (table + operation) to a workflow. Auto-generated when the workflow is saved. Example: entry condition checks `wallet_ledger` → trigger created for `wallet_ledger INSERT`. Stored in `amp_workflow_trigger`.\n\n**Execution** — A single user''s run through a workflow, tracked by a unique `inngest_run_id`. Statuses: `active` (in progress), `completed`, `failed`, `exited`.\n\n**Audience** — A saved segment backed by a system workflow. When activated, a 2-node workflow (condition → add-to-audience action) evaluates in real-time via the same CDC pipeline. See Audience Builder feature guide.\n\n**Variable Substitution** — Template syntax (`{{user.firstname}}`, `{{trigger.amount}}`) that personalizes message content and API payloads at execution time.\n\n**Node Stats** — Per-node execution counters (entered, completed, errors) displayed as overlays on the canvas. Sourced from `amp_workflow_log`.", "content_format": "markdown", "knowledge_type": "key_concepts", "perspectives": ["customer_success", "general", "product", "testing"], "output_uses": ["agent_context", "product_docs", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/amp-workflows.md#L11 2. Key Concepts", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "amp-workflows", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "c951572389206b7d3a287298daeadf6a43c2adfacaa2a05e928587d9dc3591cc", "truncated": false}, "is_active": true}, {"id": "bb422e9b-2620-5557-9e79-3468e40c99f2", "feature_slug": "amp-workflows", "title": "6a. For Customer Success / Support", "content": "**Elevator pitch:** \"Workflows automate your marketing actions. When a customer does something — earns points, makes a purchase, joins a segment — the system automatically sends messages, awards bonuses, or updates their profile based on rules you set up.\"\n\n**Top support questions:**\n\n| Question | Answer |\n|---|---|\n| \"Customer says they got a random LINE message\" | Check active workflows — find which one targets that user''s trigger event. The message came from an action node. |\n| \"Customer didn''t receive the welcome bonus\" | Check if the welcome workflow is active, if the user met the entry condition, and if the execution completed (check AMP Analytics → User Timeline). |\n| \"Customer got the same message twice\" | Check if there are duplicate workflows targeting the same trigger. Or the user may have triggered the workflow twice (two qualifying events). |\n| \"Points were awarded but no message sent\" | The workflow may have failed after the award action but before the message node. Check execution logs for errors. |\n| \"How do I stop a workflow for one customer?\" | Workflows don''t have per-user opt-out. Deactivate the workflow to stop it for everyone, or adjust the entry condition to exclude specific segments. |", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["customer_success"], "output_uses": ["agent_context", "help_center", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/amp-workflows.md#L163 6. Perspectives / 6a. For Customer Success / Support", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "amp-workflows", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "fd827eff1277ab535a8b7752a67d06049e9ffe40a8f3d4f2e25c27ee3105c3e7", "truncated": false}, "is_active": true}, {"id": "d11acb3d-a195-55ab-a61e-e31d25b4ceb8", "feature_slug": "amp-workflows", "title": "1. Overview", "content": "AMP Workflows is the marketing automation engine of the CX Platform. Merchants design automated journeys that respond to customer behavior — when a member earns points, completes a purchase, or enters an audience segment, workflows trigger and execute a chain of actions: send a LINE message, award bonus points, assign a tag, wait three days, check a condition, then branch.\n\nThe builder is a visual drag-and-drop canvas where marketing teams construct these workflows without code. Each workflow is a directed graph of nodes (conditions, actions, waits, messages) connected by edges. The system watches for database events via a CDC pipeline (Debezium → Kafka → consumer → dispatcher), matches them to active workflow triggers, and hands execution to Inngest for durable orchestration. Inngest handles retries, long waits, and state persistence — a workflow that sleeps for 7 days resumes reliably.\n\nWorkflows operate entirely in the background. Members never interact with a \"workflow\" directly — they receive its effects: a welcome LINE message, bonus points in their wallet, a tag that changes their eligibility, or a persona reassignment. The admin sees these effects tracked as an execution log with funnel analytics.", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing", "product"], "output_uses": ["agent_context", "product_docs", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/amp-workflows.md#L3 1. Overview", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "amp-workflows", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "c64b67581851442c6f62a0d5c6fbda3c7622805478a14b236dbfc9f165ad7f4c", "truncated": false}, "is_active": true}, {"id": "049fb14a-5e19-5879-8240-e46d501578d5", "feature_slug": "amp-workflows", "title": "8. Related Features", "content": "| Feature | Connection to AMP Workflows |\n|---|---|\n| Currency | Award points/tickets action writes to `wallet_ledger` via `post_wallet_transaction`. Point earning events trigger workflows via CDC. See `Currency.md`. |\n| Tags & Personas | Assign/remove tag and assign persona actions modify user profile data. Tag/persona changes can be entry conditions. See `Tag_and_Persona.md`. |\n| Tier | Tier-related conditions can gate workflow branches. Tier upgrades (future CDC source) can trigger workflows. See `Tier.md`. |\n| Rewards | Workflows do not directly issue rewards, but can trigger conditions or tag members for reward eligibility. See `Reward.md`. |\n| Forms | Submit form action populates form responses. Form submissions (future CDC source) can trigger workflows. See `Forms.md`. |\n| AMP AI Decisioning | Agent nodes invoke AI-powered decision engines within the workflow graph. See `AMP - AI Decisioning.md`. |\n| AMP Audiences | Audiences are system workflows using the same engine. Audience membership changes can trigger marketing workflows. See Audience Builder. |\n| Activity/Earning | Purchase and earning events are the primary CDC sources that trigger workflows. See `Activity_Based_Earning.md`. |", "content_format": "markdown", "knowledge_type": "related_features", "perspectives": ["general", "product"], "output_uses": ["agent_context", "product_docs"], "scope": "general", "source_ref": "requirements/feature-docs/amp-workflows.md#L259 8. Related Features", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "amp-workflows", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "8a60fc983af2c054cf994f575130dad95d0ab178a2b147c32c12c8c3d65c5053", "truncated": false}, "is_active": true}, {"id": "fa363223-ae7b-59e2-8fb7-fd50aa6360a3", "feature_slug": "amp-workflows", "title": "6c. For Testers", "content": "**Config → expected behavior:**\n\n| Config | Expected Behavior |\n|---|---|\n| Workflow `is_active = false` | No events processed, triggers ignored |\n| Entry condition on `wallet_ledger` with `transaction_type = ''earn''` | Only point-earning events trigger (not deductions) |\n| Condition node evaluates to false, no false-branch edge | Execution ends at that node (`execution_completed`) |\n| Wait node: 3 days | Inngest sleeps for 72 hours, then resumes at the next node |\n| Action node: award 100 points | `wallet_ledger` INSERT with `source_type=''amp''`, `amount=100` |\n| Action node: assign tag | `user_tags` upsert with `source_type=''amp''`, `source_id=workflow_id` |\n\n**Execution log assertions:**\n\n- ASSERT: Every execution starts with `execution_started` event (no `node_id`)\n- ASSERT: Each node produces a `node_executed` event with correct `node_id` and `node_type`\n- ASSERT: Message actions produce both `node_executed` (status: `executed`) and `action_sent` (status: `sent`)\n- ASSERT: Execution ends with `execution_completed`, `execution_failed`, or `execution_exited`\n- ASSERT: All log entries share the same `inngest_run_id` for one execution\n- ASSERT: `source_type=''amp''` on all CRM records created by workflow actions\n\n**Status model (event sourcing — all statuses are INSERT, not UPDATE):**\n\n| Event Type | When | Node Context |\n|---|---|---|\n| `execution_started` | Workflow begins for a user | No |\n| `node_executed` | A node runs | Yes |\n| `action_sent` | Message accepted by provider | Yes, with `external_message_id` |\n| `action_delivered` | Provider confirms delivery | Yes |\n| `action_failed` | Node execution error | Yes, with `error_message` |\n| `execution_completed` | All nodes finished | No |\n| `execution_failed` | Unrecoverable error | No |\n\n**Error scenarios to test:**\n- Network failure on message send → Inngest retries 3 times with exponential backoff\n- Invalid tag_id in action config → `action_failed` logged, execution may continue or fail depending on error handling\n- CDC event for a table not in the trigger registry → event ignored, no workflow fires\n- Two workflows trigger on the same event → both execute independently\n- User triggers same workflow while a previous execution is still in-flight → new execution starts (parallel runs allowed)", "content_format": "markdown", "knowledge_type": "testing_guidance", "perspectives": ["testing"], "output_uses": ["agent_context", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/amp-workflows.md#L163 6. Perspectives / 6c. For Testers", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "amp-workflows", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "154aadb7d4eef9b89219736cafcde8a01b490cc9db094d0e5dbbe6d2044ab98e", "truncated": false}, "is_active": true}, {"id": "6d278ac1-2579-59fd-b00f-8092c54f3f10", "feature_slug": "amp-workflows", "title": "5. Member Experience", "content": "**Repo:** `Rocket-CRM/loyalty-user`\n\nMembers do not interact with workflows directly. There is no workflow-specific UI in the member app. Workflows are background automation — members experience the effects.\n\n**Route map:** N/A — no member-facing routes for workflows.\n\n### Member-Visible Outcomes\n\n| Workflow Action | What the Member Sees |\n|---|---|\n| LINE Message | Push notification and message in LINE chat |\n| SMS | Text message on phone |\n| Award Currency (points) | Points balance increases, transaction appears in history |\n| Award Currency (tickets) | Ticket balance increases |\n| Assign Tag | No direct visibility (affects eligibility for rewards, missions, etc.) |\n| Assign Persona | May change visible tier benefits, reward pricing, or content |\n| Assign Earn Factor | Temporary earning boost — member sees higher points per transaction |\n| Submit Form | Form data populated on their profile |\n| Add/Remove from Audience | No direct visibility (affects future workflow targeting) |\n\n### Timing\n\n- CDC pipeline latency: ~200-500ms from database write to workflow trigger\n- Execution is durable: wait nodes pause for the configured duration, then resume\n- Message delivery depends on the channel provider (LINE: near-instant, SMS: seconds)\n- Members may receive workflow effects minutes, hours, or days after the triggering event", "content_format": "markdown", "knowledge_type": "user_experience", "perspectives": ["frontend", "marketing", "testing"], "output_uses": ["frontend_context", "marketing_content", "qa_testing"], "scope": "user_fe", "source_ref": "requirements/feature-docs/amp-workflows.md#L134 5. Member Experience", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "amp-workflows", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "bfcb25a9d07d83a05b93678182b3c0e18ba577a98f7d7eead2aaedbbac028de6", "truncated": false}, "is_active": true}, {"id": "ba3565a1-84d8-5bf1-a284-5044c1f6317c", "feature_slug": "amp-workflows", "title": "6b. For Marketing", "content": "**Value proposition:** AMP replaces manual campaign sends with automated, behavior-triggered journeys. Instead of batch-blasting a segment, workflows react to individual customer moments — a purchase, a tier upgrade, a lapsed period — and deliver the right message at the right time.\n\n**Campaign patterns:**\n1. **Welcome series** — Signup triggers: greeting → wait 2 days → check first purchase → send discount or tips\n2. **Post-purchase nurture** — Purchase triggers: thank you → wait 7 days → request review → award bonus points\n3. **Win-back** — Lapsed audience triggers: \"we miss you\" → wait 3 days → send offer → check redemption\n4. **Tier celebration** — Tier upgrade triggers: congratulations message → award bonus points → exclusive offer\n5. **Birthday campaign** — Birthday date match: greeting → birthday points → special reward offer\n\n**Metrics available in AMP Analytics:** Total triggers, unique users reached, completion rate, failure rate, in-flight count, action funnel (executed → sent → delivered → opened), daily volume trends.", "content_format": "markdown", "knowledge_type": "value_proposition", "perspectives": ["marketing", "sales"], "output_uses": ["marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/amp-workflows.md#L163 6. Perspectives / 6b. For Marketing", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "amp-workflows", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "a423bebd66426db0396a2957f36003df77a55fc8e765513169cbc474e93ccdd7", "truncated": false}, "is_active": true}, {"id": "2d934d95-582a-5e9c-a7a9-7c1788533d84", "feature_slug": "authentication-and-signup", "title": "4. Admin Journey", "content": "**Repo:** `Rocket-CRM/loyalty-admin`\n\n**Route map:**\n\n| Page name | Current route | Data source |\n|---|---|---|\n| Login | `/login` | `supabase.auth.signInWithPassword()` |\n| Merchant Settings | `/merchant-settings` | `merchant_master` |\n\n### 4a. Admin Login\n\n1. Admin navigates to the admin dashboard login page\n2. Enters email + password\n3. Standard Supabase Auth validates credentials\n4. On success: Supabase client stores session automatically, redirects to dashboard\n5. On failure: error message displayed\n\nAdmin auth uses Supabase Auth natively — no custom JWT, no LINE/OTP. The admin JWT contains `email`, `role`, and standard Supabase claims. No `merchant_id` or `phone` custom claims.\n\n### 4b. Configure Member Auth Methods\n\nThe `auth_methods` array on `merchant_master` determines which identity providers members must use. This is configured at the merchant level. When a merchant changes from `[\"tel\"]` to `[\"line\", \"tel\"]`, existing phone-only members will be prompted to link their LINE account on next login.\n\n### 4c. View Member Auth Status\n\nMember records in `user_accounts` show: `tel` (phone linked), `line_id` (LINE linked), `is_signup_form_complete` (profile submitted). Admins can inspect these fields to diagnose login issues.", "content_format": "markdown", "knowledge_type": "admin_journey", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/authentication-and-signup.md#L81 4. Admin Journey", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "authentication-and-signup", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "4f0e129f7d8fbec1ec2b6187628bd5c3b799825c15241d78130631a41cd1aa75", "truncated": false}, "is_active": true}, {"id": "0fb8a256-3b1e-512c-a45a-e4fe5c3766e6", "feature_slug": "authentication-and-signup", "title": "7. Business Rules", "content": "**Rule:** `next_step` determines the entire flow. The frontend never decides which screen to show — it follows the API instruction.\n**Example:** Member with `line_id` but no `tel`, merchant requires both → `bff-auth-complete` returns `verify_tel` → frontend shows phone input.\n\n**Rule:** `bff-auth-complete` is the single entry point for all auth scenarios. LINE-only, phone-only, both, linking a new method, and profile completion checks all route through this function.\n**Example:** Even when a member already has a JWT and needs to link LINE, the call goes through `bff-auth-complete` with the `access_token` parameter.\n\n**Rule:** Phone numbers are normalized to `+66XXXXXXXXX` before any database lookup or insert. Prevents duplicate accounts from format differences.\n**Example:** Member enters `0966564526` → stored and looked up as `+66966564526`.\n\n**Rule:** Profile completion is two-layered: (1) `is_signup_form_complete` flag for \"has ever submitted,\" (2) dynamic check for required fields with empty values.\n**Example:** Member submitted form 3 months ago (`is_signup_form_complete=true`), merchant adds new required field → member sees only the new field on next login.\n\n**Rule:** `phone` and `line_id` are deactivated in `user_field_config`. These identities are managed exclusively by the auth flow, not editable via the profile form.\n**Example:** The signup form never shows a \"phone number\" field — it''s captured during OTP verification.\n\n**Rule:** When `next_step` is `verify_line` or `verify_tel` (auth method still missing), `bff-auth-complete` skips profile template evaluation entirely and returns early.\n**Example:** Member authenticates with phone, needs LINE → response includes JWT but no `missing_data`. Profile check happens only after all auth methods are satisfied.\n\n**Rule:** LINE OAuth state is persisted to `sessionStorage` before redirect. On return, `LineCallbackHandler` restores credentials to continue the flow.\n**Example:** Member was mid-phone-OTP, taps LINE → phone `session_id` and `tel` saved → LINE redirect → on return, all credentials combined for `bff-auth-complete`.\n\n**Rule:** Custom JWT secret must match Supabase''s Legacy JWT Secret across all services. Mismatch causes `PGRST301` errors or \"Invalid signature\" failures.\n**Example:** `bff-auth-complete` signs with `SUPABASE_JWT_SECRET` → PostgREST validates with same secret → external services (crm-api) must use identical secret in `JWT_SECRET` env var.", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["customer_success", "product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/authentication-and-signup.md#L257 7. Business Rules", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "authentication-and-signup", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "70e07240b7d1ac71fafef3b02f9e87cc6c49cf1eac415b9f82cee22c04cf448a", "truncated": false}, "is_active": true}]'::jsonb) as x(
    id uuid,
    feature_slug text,
    title text,
    content text,
    content_format text,
    knowledge_type text,
    perspectives text[],
    output_uses text[],
    scope text,
    source_ref text,
    metadata jsonb,
    is_active boolean
  )
),
resolved_blocks as (
  select
    b.id,
    f.id as feature_item_id,
    b.title,
    b.content,
    b.content_format,
    b.knowledge_type::internal_knowledge_type as knowledge_type,
    b.perspectives::internal_knowledge_perspective[] as perspectives,
    b.output_uses::internal_knowledge_output_use[] as output_uses,
    b.scope::internal_knowledge_scope as scope,
    b.source_ref,
    b.metadata,
    coalesce(b.is_active, true) as is_active
  from input_blocks b
  join public.internal_knowledge_feature_items f on lower(f.slug) = lower(b.feature_slug)
)
insert into public.internal_knowledge_blocks (
  id, feature_item_id, title, content, content_format, knowledge_type,
  perspectives, output_uses, scope, source_ref, metadata, is_active, updated_at
)
select
  id,
  feature_item_id,
  title,
  content,
  content_format,
  knowledge_type,
  perspectives,
  output_uses,
  scope,
  source_ref,
  metadata,
  is_active,
  now()
from resolved_blocks
on conflict (id) do update set
  feature_item_id = excluded.feature_item_id,
  title = excluded.title,
  content = excluded.content,
  content_format = excluded.content_format,
  knowledge_type = excluded.knowledge_type,
  perspectives = excluded.perspectives,
  output_uses = excluded.output_uses,
  scope = excluded.scope,
  source_ref = excluded.source_ref,
  metadata = public.internal_knowledge_blocks.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

commit;
